package omi.jpx.fseequities.marketbyorder.flex.v1_3.enums;

import java.util.Optional;

/**
 * When the D tag was generated by a modification order, indicates whether there is a change of time priority
 *
 * <p>Backed by short. Values correspond to the wire integer encoding.</p>
 */
public enum DeleteModificationFlag {

    /**
     * Cancel Order Modification Order That Changes Time Priority Or Expired Order
     */
    CANCEL_ORDER_MODIFICATION_ORDER_THAT_CHANGES_TIME_PRIORITY_OR_EXPIRED_ORDER((short) 0, "Cancel Order Modification Order That Changes Time Priority Or Expired Order"),

    /**
     * Modification Order That Does Not Change Time Priority
     */
    MODIFICATION_ORDER_THAT_DOES_NOT_CHANGE_TIME_PRIORITY((short) 1, "Modification Order That Does Not Change Time Priority");

    private final short wire;

    private final String description;

    DeleteModificationFlag(short wire, String description) {
        this.wire = wire;
        this.description = description;
    }

    /**
     * Returns this value's encoding on the wire.
     *
     * @return the wire value
     */
    public short wire() {
        return wire;
    }

    /**
     * Returns the description the protocol specification gives this value.
     *
     * @return the description
     */
    public String description() {
        return description;
    }

    /**
     * Returns the value with the given wire encoding.
     *
     * @param wire the encoding read from the wire
     * @return the matching value, or empty when the protocol declares no value for it
     */
    public static Optional<DeleteModificationFlag> fromWire(short wire) {
        return switch (wire) {
            case 0 -> Optional.of(CANCEL_ORDER_MODIFICATION_ORDER_THAT_CHANGES_TIME_PRIORITY_OR_EXPIRED_ORDER);
            case 1 -> Optional.of(MODIFICATION_ORDER_THAT_DOES_NOT_CHANGE_TIME_PRIORITY);
            default -> Optional.empty();
        };
    }
}
